const updateCalendarEventsBatch = `-- name: UpdateCalendarEventsBatch :many
UPDATE calendar_event AS e
SET title = data.title, description = data.description, starts_at = data.starts_at,
    ends_at = data.ends_at, all_day = data.all_day, location = data.location, updated_at = now()
FROM (
    SELECT
        unnest($2::uuid[]) AS id,
        unnest($3::text[]) AS title,
        unnest($4::text[]) AS description,
        unnest($5::timestamptz[]) AS starts_at,
        unnest($6::timestamptz[]) AS ends_at,
        unnest($7::bool[]) AS all_day,
        unnest($8::text[]) AS location
) AS data
WHERE e.id = data.id AND e.workspace_id = $1
RETURNING e.id
`

type UpdateCalendarEventsBatchParams struct {
	WorkspaceID  pgtype.UUID          `json:"workspace_id"`
	Ids          []pgtype.UUID        `json:"ids"`
	Titles       []string             `json:"titles"`
	Descriptions []string             `json:"descriptions"`
	StartsAts    []pgtype.Timestamptz `json:"starts_ats"`
	EndsAts      []pgtype.Timestamptz `json:"ends_ats"`
	AllDays      []bool               `json:"all_days"`
	Locations    []string             `json:"locations"`
}

// Batch variant of UpdateCalendarEvent for ImportGoogleCalendar, which
// otherwise updates one Google event at a time (up to googleImportMaxEvents
// per import). timezone/issue_id/project_id are left untouched, same as the
// single-row update always re-setting them to their own current value.
func (q *Queries) UpdateCalendarEventsBatch(ctx context.Context, arg UpdateCalendarEventsBatchParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, updateCalendarEventsBatch,
		arg.WorkspaceID,
		arg.Ids,
		arg.Titles,
		arg.Descriptions,
		arg.StartsAts,
		arg.EndsAts,
		arg.AllDays,
		arg.Locations,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

